  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 The Preterite: Spelling Changes and Stem Changes$j$, $j${"readings": [{"title": "Psalm 105 (King James Version)", "url": "/portal/bible/Psalms/105"}], "body": "Psalm 105:5 says, Remember his marvellous works that he hath done, his wonders, and the judgments of his mouth. Remembering what God has done begins with the past tense. In Spanish 1 you met the preterite, which tells about completed actions. Here we add the spelling changes.\n\nReview the endings. Ar verbs take é, aste, ó, amos, aron. Er and ir verbs take í, iste, ió, imos, ieron.\n\nIn the yo form, verbs that end in car, gar and zar change spelling to keep the sound. Buscar becomes busqué, pagar becomes pagué and empezar becomes empecé. Compare: Busqué mi Biblia. Pagué la cuenta. Empecé a leer.\n\nWhen an unaccented i falls between two vowels, it becomes y. Leer is leí, leíste, leyó, leímos, leyeron. Oír is oí, oíste, oyó, oímos, oyeron. Creer is creí, creíste, creyó, creímos, creyeron.\n\nStem changing ir verbs change in the él and ellos forms only: dormir becomes durmió and durmieron, pedir becomes pidió and pidieron, and servir becomes sirvió and sirvieron.\n\nWorked example: Ayer leí el Salmo 23. Mi hermana pidió agua. Common mistake: writing leió for leyó. The i becomes y between vowels.\n\nYour task: (1) Write the yo form of buscar, pagar and empezar in the preterite. (2) Write five sentences about yesterday with leer, oír, pedir, dormir and servir.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 105:5 says, Remember his marvellous works that he hath done. Remembering begins with the past tense.\n\nNow watch this. Review the endings. Ar verbs: é, aste, ó, amos, aron. Er and ir verbs: í, iste, ió, imos, ieron.\n\nIn the yo form, car becomes qué, gar becomes gué and zar becomes cé. Busqué, pagué, empecé.\n\nWhen i falls between two vowels, it becomes y. Leyó, leyeron, oyó, oyeron, creyó.\n\nStem changing ir verbs change only in the él and ellos forms. Durmió, durmieron, pidió, pidieron.\n\nYour task is to write the yo forms and five sentences about yesterday. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 The Preterite: Spelling Changes and Stem Changes$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Irregular Verbs in the Preterite$j$, $j${"readings": [{"title": "Genesis 1 (King James Version)", "url": "/portal/bible/Genesis/1"}], "body": "Genesis 1:3 says, And God said, Let there be light: and there was light. In Spanish, Dios dijo, and the verb dijo is one of many irregular preterites you now need.\n\nMany irregular verbs use a special stem and one set of endings with no accents: e, iste, o, imos, ieron. Here are the stems.\nEstar is estuv: estuve, estuviste, estuvo, estuvimos, estuvieron.\nTener is tuv: tuve. Poder is pud: pude. Poner is pus: puse. Saber is sup: supe. Querer is quis: quise. Venir is vin: vine. Hacer is hic: hice, hiciste, hizo, hicimos, hicieron.\nDecir is dij and traer is traj. These take eron instead of ieron: dijeron, trajeron.\n\nDar and ver share the same endings as regular er and ir verbs but have no accents: di, diste, dio, dimos, dieron and vi, viste, vio, vimos, vieron.\n\nWorked example: Ayer estuve en la iglesia y vine a casa a las dos. Mis padres hicieron la cena. Ellos dijeron la verdad. Common mistake: adding accents or the wrong endings, as in tuvé. The yo form is tuve with no accent.\n\nYour task: (1) Conjugate tener and decir in the preterite. (2) Write six sentences about last weekend using estuve, hice, tuve, pude, dije and vi.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Genesis 1:3 says, And God said, Let there be light: and there was light. In Spanish, Dios dijo. Dijo is an irregular preterite.\n\nNow watch this. Many irregular verbs take a special stem and these endings: e, iste, o, imos, ieron. No accents.\n\nEstar is estuve. Tener is tuve. Poder is pude. Poner is puse. Saber is supe. Querer is quise. Venir is vine. Hacer is hice, and the él form is hizo.\n\nDecir and traer use eron. Dijeron, trajeron.\n\nDar and ver are di, diste, dio, dimos, dieron, and vi, viste, vio, vimos, vieron.\n\nYour task is to conjugate tener and decir and write six sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Irregular Verbs in the Preterite$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 The Imperfect Tense$j$, $j${"readings": [{"title": "Luke 2 (King James Version)", "url": "/portal/bible/Luke/2"}], "body": "Luke 2:8 says, And there were in the same country shepherds abiding in the field, keeping watch over their flock by night. This verse describes a scene that was going on, and Spanish uses the imperfect tense for that. The imperfect describes habitual actions, ongoing actions, descriptions, ages and the time of day in the past.\n\nFor ar verbs the endings are aba, abas, aba, ábamos, aban. Hablar becomes hablaba, hablabas, hablaba, hablábamos, hablaban. For er and ir verbs the endings are ía, ías, ía, íamos, ían. Comer becomes comía, comías, comía, comíamos, comían.\n\nOnly three verbs are irregular in the imperfect. Ser is era, eras, era, éramos, eran. Ir is iba, ibas, iba, íbamos, iban. Ver is veía, veías, veía, veíamos, veían.\n\nWorked example: Cuando era niño, íbamos a la iglesia cada domingo. Mi abuela cantaba en el coro. Hacía calor y eran las tres. Common mistake: using the preterite for a habit. Say Jugaba todos los días, not Jugué todos los días. English phrases that signal the imperfect are used to, would and was or were plus ing.\n\nYour task: (1) Conjugate vivir, ser and ir in the imperfect. (2) Write six sentences about your childhood: where you lived, what you did each week, and what you were like.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Luke 2:8 says, There were in the same country shepherds abiding in the field, keeping watch over their flock by night. This describes a scene that was going on. Spanish uses the imperfect for that.\n\nNow watch this. The imperfect tells what used to happen, what was going on, descriptions, ages and time.\n\nAr verbs: aba, abas, aba, ábamos, aban. Er and ir verbs: ía, ías, ía, íamos, ían.\n\nThree verbs are irregular. Ser is era. Ir is iba. Ver is veía.\n\nCuando era niño, íbamos a la iglesia cada domingo. Hacía calor y eran las tres.\n\nYour task is to conjugate vivir, ser and ir and write six sentences about your childhood. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 The Imperfect Tense$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Preterite and Imperfect Together$j$, $j${"readings": [{"title": "John 9 (King James Version)", "url": "/portal/bible/John/9"}], "body": "In John 9:25 the man healed of blindness said, One thing I know, that, whereas I was blind, now I see. His words show the two ideas of this lesson: what was ongoing and what changed. Spanish uses the imperfect for the background and the preterite for the events that move the story forward.\n\nUse the imperfect for habits, descriptions, ongoing actions, age, weather and time. Use the preterite for completed actions, a specific time, a sudden event and a change. Compare: Llovía cuando salí de la iglesia. It was raining (background) when I left (event). Mientras leía, llegó mi amigo. While I was reading (ongoing), my friend arrived (event).\n\nSignal words help. Imperfect: siempre, a menudo, todos los días, cada año, mientras, de niño. Preterite: ayer, anoche, una vez, de repente, el lunes, la semana pasada.\n\nA few verbs change meaning. Supe means I found out, conocí means I met, pude means I managed, and no quise means I refused. The imperfect forms sabía, conocía, podía and quería describe a state.\n\nWorked example: De niño, vivía en Cuba. Un día, mi familia salió en un barco. Common mistake: choosing only one tense for a whole story. Mix them, with the imperfect setting the scene and the preterite moving the action.\n\nYour task: (1) Write a paragraph of eight sentences about a memory using both tenses. (2) Underline each preterite and circle each imperfect.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, John 9:25 says, Whereas I was blind, now I see. One tense describes what was, and one tells what changed.\n\nNow watch this. The imperfect sets the scene: habits, descriptions, ongoing actions, age, weather and time. The preterite moves the story: completed actions, a specific time and sudden events.\n\nLlovía cuando salí de la iglesia. Mientras leía, llegó mi amigo.\n\nSignal words help. For the imperfect: siempre, todos los días, mientras. For the preterite: ayer, anoche, de repente, una vez.\n\nSome verbs change meaning. Supe means I found out. Conocí means I met.\n\nYour task is to write a paragraph of eight sentences about a memory using both tenses. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Preterite and Imperfect Together$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Talking About the Past$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Psalm 105:5 says, Remember his marvellous works that he hath done, his wonders, and the judgments of his mouth.\n\nPart 1: Conjugate one regular ar, er and ir verb in the preterite, and explain the spelling changes for buscar, pagar, empezar, leer and oír.\nPart 2: Conjugate tener, estar, hacer and decir in the preterite and write four sentences.\nPart 3: Conjugate one regular verb and ser, ir and ver in the imperfect, and explain when to use the imperfect.\nPart 4: Write a Spanish paragraph of at least ten sentences about a childhood memory or a family trip using both the preterite and the imperfect, with signal words.\nPart 5: Explain the difference in meaning between supe and sabía and between conocí and conocía.\nPart 6: Explain how remembering what God has done, in Psalm 105:5 or Psalm 78:4, can shape the way you tell your own story.", "rubric": "100 points. Part 1: 15 points. Part 2: 15 points. Part 3: 15 points. Part 4: 30 points. Part 5: 10 points. Part 6: 10 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Talking About the Past$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Telling Our Stories$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells in English about one memory from your childhood, (2) shares at least three Spanish sentences about it using the imperfect and the preterite, and (3) connects your answer to Psalm 105:5 or John 9:25. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it important for believers to tell what God has done in the past tense?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Telling Our Stories$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Preterite: Spelling Changes and Stem Changes$j$, $j${"questions": [{"q": "The yo preterite of buscar is:", "options": ["Buscé", "Busco", "Buscí", "Busqué"]}, {"q": "Ella leyó means:", "options": ["She will read", "She read", "She reads", "She was reading"]}, {"q": "The ellos preterite of dormir is:", "options": ["Dormieron", "Duermen", "Dormían", "Durmieron"]}, {"q": "The yo preterite of empezar is:", "options": ["Empezí", "Empezé", "Empiezo", "Empecé"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Preterite: Spelling Changes and Stem Changes$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,3,3}'::int[], array[$j$Car changes to qué in the yo form.$j$,$j$Leyó is the preterite of leer.$j$,$j$Ir stem changers change o to u in the third person.$j$,$j$Zar changes to cé.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Preterite: Spelling Changes and Stem Changes$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Irregular Verbs in the Preterite$j$, $j${"questions": [{"q": "The yo preterite of tener is:", "options": ["Tuvé", "Tuve", "Tené", "Tenié"]}, {"q": "Ellos dijeron means:", "options": ["They will say", "They say", "They said", "They were saying"]}, {"q": "The él preterite of hacer is:", "options": ["Hace", "Hicó", "Hizo", "Hacío"]}, {"q": "The yo preterite of ver is:", "options": ["Vio", "Veí", "Vi", "Vide"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Irregular Verbs in the Preterite$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,2}'::int[], array[$j$Tener uses the stem tuv with no accent.$j$,$j$Dijeron is the preterite of decir.$j$,$j$Hacer changes to hizo in the él form.$j$,$j$Ver is vi with no accent.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Irregular Verbs in the Preterite$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: The Imperfect Tense$j$, $j${"questions": [{"q": "The imperfect of hablar for yo is:", "options": ["Hablaría", "Hablo", "Hablé", "Hablaba"]}, {"q": "Íbamos a la iglesia means:", "options": ["We used to go to church", "We will go to church", "We went once", "We are going"]}, {"q": "Which verb is irregular in the imperfect?", "options": ["Vivir", "Ser", "Hablar", "Comer"]}, {"q": "The imperfect is used for:", "options": ["Commands", "Habits and descriptions in the past", "The future", "A single completed event"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Imperfect Tense$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,1}'::int[], array[$j$Ar verbs take aba.$j$,$j$Íbamos is the imperfect of ir.$j$,$j$Ser, ir and ver are the irregular imperfects.$j$,$j$The imperfect describes ongoing or repeated past actions.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: The Imperfect Tense$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Preterite and Imperfect Together$j$, $j${"questions": [{"q": "Which tense describes the background of a story?", "options": ["Command", "Preterite", "Imperfect", "Future"]}, {"q": "De repente signals the:", "options": ["Imperfect", "Preterite", "Future", "Present"]}, {"q": "Mientras leía, llegó mi amigo. Leía is imperfect because it is:", "options": ["An ongoing action", "A future action", "A completed action", "A command"]}, {"q": "Conocí a Pedro ayer means:", "options": ["I will meet Pedro", "I met Pedro yesterday", "I knew Pedro yesterday", "I used to know Pedro"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Preterite and Imperfect Together$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,1}'::int[], array[$j$The imperfect sets the scene.$j$,$j$A sudden event uses the preterite.$j$,$j$The imperfect shows the action in progress.$j$,$j$Conocí in the preterite means I met.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Preterite and Imperfect Together$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Talking About the Past$j$, $j${"questions": [{"q": "The yo preterite of pagar is:", "options": ["Pagué", "Pago", "Pagé", "Pagí"]}, {"q": "Ellos oyeron means:", "options": ["They will hear", "They hear", "They heard", "They listen"]}, {"q": "The yo preterite of poder is:", "options": ["Puedo", "Pudé", "Podí", "Pude"]}, {"q": "Yo era is:", "options": ["Future of ser", "Preterite of ser", "Present of ir", "Imperfect of ser"]}, {"q": "Todos los días jugábamos signals the:", "options": ["Imperfect", "Preterite", "Command", "Future"]}, {"q": "Anoche cenamos pizza uses the preterite because:", "options": ["It is a future plan", "It is a description", "It happened once, last night", "It was a habit"]}, {"q": "Nosotros fuimos can be the preterite of:", "options": ["Ir or ser", "Tener", "Poner", "Hacer"]}, {"q": "Íbamos, era and veía are all:", "options": ["Present forms", "Future forms", "Imperfect forms", "Preterite forms"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Talking About the Past$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3,0,2,0,2}'::int[], array[$j$Gar changes to gué.$j$,$j$Oyeron is the preterite of oír.$j$,$j$Poder uses the stem pud.$j$,$j$Era is the imperfect of ser.$j$,$j$Habitual actions use the imperfect.$j$,$j$A specific completed action uses the preterite.$j$,$j$Ir and ser share the preterite fui.$j$,$j$These are the three irregular imperfects.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Talking About the Past$j$ on conflict (item_id) do nothing;
